source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    crosses = []
    arms = set()
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            pts = ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1))
            if all(grid[y][x] == 2 for y, x in pts):
                crosses.append((r, c))
                arms.update(pts)
    nodes = [(r, c, True) for r, c in crosses]
    nodes += [(r, c, False) for r in range(h) for c in range(w)
              if grid[r][c] == 2 and (r, c) not in arms]
    for i, (r1, c1, cross1) in enumerate(nodes):
        for r2, c2, cross2 in nodes[i + 1:]:
            if r1 == r2:
                lo, hi = sorted((c1, c2))
                if not any((r1, c) in crosses for c in range(lo + 1, hi)):
                    start = lo + (1 if not (cross1 if c1 == lo else cross2) else 2)
                    end = hi - (1 if not (cross1 if c1 == hi else cross2) else 2)
                    for c in range(start, end + 1):
                        if out[r1][c] == 0: out[r1][c] = 1
            elif c1 == c2:
                lo, hi = sorted((r1, r2))
                if not any((r, c1) in crosses for r in range(lo + 1, hi)):
                    start = lo + (1 if not (cross1 if r1 == lo else cross2) else 2)
                    end = hi - (1 if not (cross1 if r1 == hi else cross2) else 2)
                    for r in range(start, end + 1):
                        if out[r][c1] == 0: out[r][c1] = 1
    return out
'''
